package payment

import("context";"crypto/rand";"encoding/hex";"fmt";"time";"github.com/jackc/pgx/v5";"github.com/jackc/pgx/v5/pgxpool")
type Service struct{db *pgxpool.Pool}
func NewService(db *pgxpool.Pool)*Service{return &Service{db:db}}
type Intent struct{PublicID string `json:"public_id"`;Amount int64 `json:"amount"`;Currency string `json:"currency"`;Provider string `json:"provider"`;Status string `json:"status"`;ExpiresAt time.Time `json:"expires_at"`}
type CreateIntentInput struct{SchoolPublicID string `json:"school_public_id"`;EnrollmentPublicID string `json:"enrollment_public_id"`;GuardianPublicID string `json:"guardian_public_id"`;Amount int64 `json:"amount"`;Provider string `json:"provider"`}
type CashInput struct{SchoolPublicID string `json:"school_public_id"`;EnrollmentPublicID string `json:"enrollment_public_id"`;Amount int64 `json:"amount"`}
type PaymentResult struct{PaymentPublicID string `json:"payment_public_id"`;ReceiptNumber string `json:"receipt_number"`;Amount int64 `json:"amount"`;Allocated int64 `json:"allocated"`;RemainingBalance int64 `json:"remaining_balance"`;Status string `json:"status"`}
func publicID(prefix string)string{b:=make([]byte,6);_,_=rand.Read(b);return prefix+"-"+time.Now().Format("060102")+"-"+hex.EncodeToString(b)}
func(s *Service)CreateIntent(ctx context.Context,in CreateIntentInput)(Intent,error){if in.Amount<=0{return Intent{},fmt.Errorf("amount must be positive")};if in.Provider!="ORANGE_MONEY"&&in.Provider!="MOOV_MONEY"{return Intent{},fmt.Errorf("unsupported provider")};id:=publicID("PI");expires:=time.Now().Add(20*time.Minute);var o Intent;e:=s.db.QueryRow(ctx,`INSERT INTO payment_intents(public_id,school_id,student_id,enrollment_id,guardian_id,amount,provider,status,expires_at) SELECT $3,e.school_id,e.student_id,e.id,g.id,$4,$5,'CREATED',$6 FROM enrollments e JOIN schools s ON s.id=e.school_id LEFT JOIN guardians g ON g.public_id=NULLIF($2,'') WHERE s.public_id=$1 AND e.public_id=$7 AND e.status='ACTIVE' AND (NULLIF($2,'') IS NULL OR EXISTS(SELECT 1 FROM student_guardians sg WHERE sg.student_id=e.student_id AND sg.guardian_id=g.id AND sg.can_pay=true)) AND $4 <= (SELECT COALESCE(sum(balance),0) FROM student_charges sc WHERE sc.enrollment_id=e.id AND sc.status<>'CANCELLED') RETURNING public_id,amount,currency,provider,status,expires_at`,in.SchoolPublicID,in.GuardianPublicID,id,in.Amount,in.Provider,expires,in.EnrollmentPublicID).Scan(&o.PublicID,&o.Amount,&o.Currency,&o.Provider,&o.Status,&o.ExpiresAt);return o,e}
func(s *Service)RecordCash(ctx context.Context,in CashInput)(PaymentResult,error){return s.settle(ctx,"",in.SchoolPublicID,in.EnrollmentPublicID,in.Amount,"CASH","","")}
func(s *Service)ConfirmCallback(ctx context.Context,cb Callback)(PaymentResult,error){if cb.EventID==""||cb.ProviderReference==""{return PaymentResult{},fmt.Errorf("event_id and provider_reference are required")};tx,e:=s.db.Begin(ctx);if e!=nil{return PaymentResult{},e};defer tx.Rollback(ctx);var intentID,schoolID,studentID,enrollmentID,status,provider string;var amount int64;e=tx.QueryRow(ctx,`SELECT id::text,school_id::text,student_id::text,enrollment_id::text,status,provider,amount FROM payment_intents WHERE public_id=$1 FOR UPDATE`,cb.IntentPublicID).Scan(&intentID,&schoolID,&studentID,&enrollmentID,&status,&provider,&amount);if e!=nil{return PaymentResult{},e};if provider!=cb.Provider{return PaymentResult{},fmt.Errorf("provider mismatch")};var existing string;e=tx.QueryRow(ctx,`SELECT COALESCE(payment_id::text,'') FROM provider_transactions WHERE provider=$1 AND event_id=$2`,cb.Provider,cb.EventID).Scan(&existing);if e==nil{if existing==""{return PaymentResult{Status:"PENDING"},nil};return s.resultByPaymentID(ctx,existing)};if e!=pgx.ErrNoRows{return PaymentResult{},e};_,e=tx.Exec(ctx,`INSERT INTO provider_transactions(payment_intent_id,provider,provider_reference,provider_status,event_id,callback_payload,confirmed_at) VALUES($1::uuid,$2,$3,$4,$5,jsonb_build_object('intent_public_id',$6),now())`,intentID,cb.Provider,cb.ProviderReference,cb.Status,cb.EventID,cb.IntentPublicID);if e!=nil{return PaymentResult{},e};if cb.Status!="SUCCESS"{_,e=tx.Exec(ctx,`UPDATE payment_intents SET status=CASE WHEN $2='FAILED' THEN 'FAILED' WHEN $2='CANCELLED' THEN 'CANCELLED' ELSE status END,updated_at=now() WHERE id=$1::uuid`,intentID,cb.Status);if e!=nil{return PaymentResult{},e};if e=tx.Commit(ctx);e!=nil{return PaymentResult{},e};return PaymentResult{Amount:amount,Status:cb.Status},nil};if status=="SUCCEEDED"{return PaymentResult{},fmt.Errorf("intent already settled")};if e=tx.Commit(ctx);e!=nil{return PaymentResult{},e};return s.settle(ctx,cb.IntentPublicID,"","",amount,cb.Provider,cb.ProviderReference,cb.EventID)}
func(s *Service)settle(ctx context.Context,intentPublicID,schoolPublicID,enrollmentPublicID string,amount int64,method,providerRef,eventID string)(PaymentResult,error){tx,e:=s.db.Begin(ctx);if e!=nil{return PaymentResult{},e};defer tx.Rollback(ctx);var enrollmentID,schoolID,studentID string;var balance int64;if intentPublicID!=""{e=tx.QueryRow(ctx,`SELECT e.id::text,e.school_id::text,e.student_id::text,COALESCE(sum(sc.balance),0) FROM payment_intents pi JOIN enrollments e ON e.id=pi.enrollment_id JOIN student_charges sc ON sc.enrollment_id=e.id AND sc.status<>'CANCELLED' WHERE pi.public_id=$1 AND pi.status<>'SUCCEEDED' GROUP BY e.id`,intentPublicID).Scan(&enrollmentID,&schoolID,&studentID,&balance)}else{e=tx.QueryRow(ctx,`SELECT e.id::text,e.school_id::text,e.student_id::text,COALESCE(sum(sc.balance),0) FROM enrollments e JOIN schools s ON s.id=e.school_id JOIN student_charges sc ON sc.enrollment_id=e.id AND sc.status<>'CANCELLED' WHERE s.public_id=$1 AND e.public_id=$2 AND e.status='ACTIVE' GROUP BY e.id`,schoolPublicID,enrollmentPublicID).Scan(&enrollmentID,&schoolID,&studentID,&balance)};if e!=nil{return PaymentResult{},e};if amount>balance{return PaymentResult{},fmt.Errorf("payment exceeds remaining balance")};pid:=publicID("PAY");var paymentID string;e=tx.QueryRow(ctx,`INSERT INTO payments(public_id,school_id,student_id,enrollment_id,payment_intent_id,amount,payment_method,status,paid_at) VALUES($1,$2::uuid,$3::uuid,$4::uuid,(SELECT id FROM payment_intents WHERE public_id=NULLIF($5,'')),$6,$7,'SUCCESS',now()) RETURNING id::text`,pid,schoolID,studentID,enrollmentID,intentPublicID,amount,method).Scan(&paymentID);if e!=nil{return PaymentResult{},e};remaining:=amount;rows,e:=tx.Query(ctx,`SELECT id::text,balance FROM student_charges WHERE enrollment_id=$1::uuid AND balance>0 AND status<>'CANCELLED' ORDER BY due_date NULLS LAST,created_at FOR UPDATE`,enrollmentID);if e!=nil{return PaymentResult{},e};type c struct{id string;b int64};var cs []c;for rows.Next(){var x c;if e=rows.Scan(&x.id,&x.b);e!=nil{rows.Close();return PaymentResult{},e};cs=append(cs,x)};rows.Close();for _,x:=range cs{if remaining==0{break};a:=x.b;if a>remaining{a=remaining};if _,e=tx.Exec(ctx,`INSERT INTO payment_allocations(payment_id,student_charge_id,amount)VALUES($1::uuid,$2::uuid,$3)`,paymentID,x.id,a);e!=nil{return PaymentResult{},e};if _,e=tx.Exec(ctx,`UPDATE student_charges SET amount_paid=amount_paid+$2,balance=balance-$2,status=CASE WHEN balance-$2=0 THEN 'PAID' ELSE 'PARTIAL' END,updated_at=now() WHERE id=$1::uuid`,x.id,a);e!=nil{return PaymentResult{},e};remaining-=a};if remaining!=0{return PaymentResult{},fmt.Errorf("unable to allocate full payment")};receipt:=publicID("REC");if _,e=tx.Exec(ctx,`INSERT INTO receipts(public_id,school_id,payment_id,receipt_number,verification_token,issued_at)VALUES($1,$2::uuid,$3::uuid,$1,$4,now())`,receipt,schoolID,paymentID,publicID("V"));e!=nil{return PaymentResult{},e};if intentPublicID!=""{if _,e=tx.Exec(ctx,`UPDATE payment_intents SET status='SUCCEEDED',updated_at=now() WHERE public_id=$1`,intentPublicID);e!=nil{return PaymentResult{},e};if _,e=tx.Exec(ctx,`UPDATE provider_transactions SET payment_id=$1::uuid WHERE provider=$2 AND event_id=$3`,paymentID,method,eventID);e!=nil{return PaymentResult{},e}};if e=tx.Commit(ctx);e!=nil{return PaymentResult{},e};return PaymentResult{pid,receipt,amount,amount,balance-amount,"SUCCESS"},nil}
func(s *Service)resultByPaymentID(ctx context.Context,id string)(PaymentResult,error){var r PaymentResult;e:=s.db.QueryRow(ctx,`SELECT p.public_id,r.receipt_number,p.amount,p.amount,COALESCE((SELECT sum(balance) FROM student_charges WHERE enrollment_id=p.enrollment_id AND status<>'CANCELLED'),0),p.status FROM payments p JOIN receipts r ON r.payment_id=p.id WHERE p.id=$1::uuid`,id).Scan(&r.PaymentPublicID,&r.ReceiptNumber,&r.Amount,&r.Allocated,&r.RemainingBalance,&r.Status);return r,e}
